/**
 * The printed homing-weapon counter art, lifted from the Aurelian Ship
 * Book's Expansion 5 counter sheet. Generated by
 * tools/extract_plasma_art.py — edit that, not this.
 *
 * `bolt` is the plasma torpedo: the fiery projectile the rules illustrate
 * in flight, drawn nose-up so the map can turn it onto its bearing.
 * `sphere` is the enveloping plasma (ENVLP, F5.4), which has no bearing
 * to speak of and is drawn as it sits.
 *
 * Both are PNGs with the counter background keyed out, so the glow fades
 * into the starfield instead of sitting in a black box.
 */

export interface PlasmaArt {
  /** A data: URI, so the art travels with the bundle and works offline. */
  href: string
  width: number
  height: number
}

export const PLASMA_ART: Record<'bolt' | 'sphere', PlasmaArt> = {
  bolt: {
    width: 40,
    height: 133,
    href: 'data:image/png;base64,',
  },
  sphere: {
    width: 64,
    height: 89,
    href: 'data:image/png;base64,',
  },
}
